mapper.select:
select pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.purchase_qty as purchaseQty, pod.plan_delivery_date as planDeliveryDate, po.code as code, po.type as type, po.source_id as sourceId, po.source_code as sourceCode, po.source_type as sourceType, po.subcontract_type as subcontractType, po.receive_org_name as receiveOrgName, po.purchase_user_name as purchaseUserName, po.delivery_warehouse_id as deliveryWarehouseId, po.delivery_warehouse_name as deliveryWarehouseName, pod.is_gift as isGift, pod.is_urgent as isUrgent, pod.remark as remark, pod.id as purchaseOrderDetailId, pod.variant_property as variantProperty, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency, pod.currency_symbol as currencySymbol, pod.warehouse_location as warehouseLocation from purchase_order po inner join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false
po.is_deleted = false and po.approve_status = 'approve' and po.invalid_status = false
and po.id = #{params.purchaseOrderId}
and pod.sku_no in
#{item}
AND pod.sku_no ILIKE concat('%',#{params.remoteSearchSku}::text,'%')

select ID, purchase_order_id, purchase_date, subcontract_type, sku_id, sku_no, product_name, declare_model, declare_name, tax_price, currency, currency_symbol, purchase_qty, purchase_amount, plan_delivery_date, is_gift, remark, execution_status, tax_rate, is_urgent, variant_property, is_end_receive, warehouse_location, source_detail_id from ( select pod.purchase_order_id, po.purchase_date, po.subcontract_type, pod.id, pod.sku_id , pod.sku_no, pod.product_name, pod.declare_model, pod.declare_name, pod.tax_price, pod.currency, pod.currency_symbol, pod.purchase_qty, pod.purchase_amount, pod.plan_delivery_date, pod.is_gift, pod.remark, pod.execution_status, pod.tax_rate, pod.is_urgent, pod.variant_property, pod.is_end_receive, pod.warehouse_location, pod.source_detail_id, row_number() over(partition by pod.sku_id order by po.purchase_date desc nulls last,po.update_time desc) as rn from purchase_order_detail pod inner join purchase_order po on pod.purchase_order_id = po.id and po.is_deleted = false where po.approve_status = 'approve' and pod.is_deleted = false and pod.sku_id in
#{id}
) m WHERE m.rn = 1

select ID, purchase_order_id, purchase_date, subcontract_type, sku_id, sku_no, product_name, declare_model, declare_name, tax_price, currency, currency_symbol, purchase_qty, purchase_amount, plan_delivery_date, is_gift, remark, execution_status, tax_rate, is_urgent, variant_property, is_end_receive, warehouse_location, source_detail_id from ( select pod.purchase_order_id, po.purchase_date, po.subcontract_type, pod.id, pod.sku_id , pod.sku_no, pod.product_name, pod.declare_model, pod.declare_name, pod.tax_price, pod.currency, pod.currency_symbol, pod.purchase_qty, pod.purchase_amount, pod.plan_delivery_date, pod.is_gift, pod.remark, pod.execution_status, pod.tax_rate, pod.is_urgent, pod.variant_property, pod.is_end_receive, pod.warehouse_location, pod.source_detail_id, row_number() over(partition by pod.sku_id order by po.create_time desc nulls last,po.update_time desc) as rn from purchase_order_detail pod inner join purchase_order po on pod.purchase_order_id = po.id and po.is_deleted = false where po.approve_status = 'approve' and pod.is_deleted = false and pod.sku_id in
#{id}
) m WHERE m.rn = 1

select count(pod.*) from purchase_order_detail pod
    left join purchase_order po on pod.purchase_order_id = po.id and po.is_deleted = false
    left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false
where pos.supplier_id = #{supplierId}
  and pod.confirm_date is not null
  and pod.confirm_date between #{startTime} and #{endTime}

select po.code, pod.id as detailId, pod.sku_no as skuNo from purchase_order po left join purchase_order_detail pod on po.id = pod.purchase_order_id and pod.is_deleted = false
po.is_deleted = false and po.invalid_status = false and po.code in
#{item}
and pod.sku_no in
#{item}

select po.id as purchaseOrderId, pos.supplier_id as supplierId, pod.id as purchaseOrderDetailId, pod.sku_id as skuId, pod.purchase_qty as purchaseQty, pod.tax_price as taxPrice from purchase_order_detail pod inner join purchase_order po on pod.purchase_order_id = po.id and po.is_deleted = false left join purchase_order_supplier pos on po.id = pos.purchase_order_id and pos.is_deleted = false
pod.is_deleted = false and po.invalid_status = false and pod.execution_status not in ('finish','closed') and (
pos.supplier_id = #{item.supplierId} and pod.sku_id = #{item.skuId} and #{item.maxQty} > pod.purchase_qty and pod.purchase_qty >= #{item.minQty}
)
